from flask import Flask, jsonify, request

app = Flask(__name__)
todos = [{"id": 1, "title": "Buy milk", "done": False}, {"id": 2, "title": "Call Ana", "done": True}]

@app.route("/todos")
def list_todos():
    return jsonify(todos)


@app.route("/todos/<int:todo_id>")
def get_todo(todo_id):
    for todo in todos:
        if todo["id"] == todo_id:
            return todo
    return {"error": "not found"}, 404

